<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Simulation Preview | Artemis 2.0</title><link rel="stylesheet" href="{{ asset('style.css') }}?v=198"><style>#quiz-screen{display:flex;flex-direction:column}.preview-start{position:fixed;inset:0;z-index:8000;display:grid;place-items:center;background:rgba(3,24,44,.7);padding:1rem}.preview-start article{width:min(500px,100%);padding:1.5rem;border-radius:18px;background:white;color:#073b65}.preview-start p{margin:1rem 0;line-height:1.6}.preview-start button{min-height:44px}.preview-note{font-size:.75rem}#preview-message{color:#dc2626;margin:.75rem 0}</style></head>
<body class="light-mode"><section id="quiz-screen" class="screen active {{ $prometric ? 'prometric-simulation-exam' : '' }}">
<header class="exam-environment-header"><div class="exam-brand"><span class="exam-brand-mark">A2</span><strong>Artemis 2.0</strong><span>{{ $prometric ? 'PROMETRIC RN Simulation Test' : 'Simulation Test' }}</span></div><div class="exam-header-progress"><div class="exam-progress-meta"><strong>Question <span id="preview-current">1</span> of {{ $questions->count() }}</strong><span>PREVIEW ONLY</span></div><div class="quiz-progress"><div class="quiz-progress-bar" id="preview-progress"></div></div></div><div class="exam-header-actions"><div id="quiz-timer">300:00</div><button class="exam-close-btn" id="preview-close" aria-label="Close preview">×</button></div></header>
@if($prometric)
<div class="prometric-candidate-strip">Candidate: Preview Learner</div>
@endif
<main class="exam-environment-body"><article class="quiz-question-card"><span class="quiz-response-label">Multiple Choice</span><div id="preview-image" style="text-align:center;margin-bottom:1.5rem"></div><h3 id="preview-question"></h3><p class="quiz-answer-instruction">Select the best answer.</p><div class="options-list" id="preview-options"></div></article></main>
<footer class="exam-environment-footer"><div class="exam-footer-controls"><button class="exam-previous-btn" id="preview-previous">‹ Previous</button><label class="exam-review-toggle"><input type="checkbox" id="preview-mark"><span>Mark for Review</span></label></div><button class="btn-primary exam-submit-btn" id="preview-next">Save &amp; Continue</button></footer></section>
<style>
.preview-start-actions{display:flex;flex-wrap:wrap;align-items:stretch;gap:12px;margin-top:20px}
.preview-start-actions .btn-primary,.preview-start-actions .btn-ghost{display:inline-flex;align-items:center;justify-content:center;min-height:44px;margin:0;text-align:center;text-decoration:none}
</style>
<div class="preview-start" id="preview-start"><article><h2>Preview Simulation Test</h2><p>{{ $testBank->title }}</p><p>This is an interface preview using up to 150 active course questions. The timer is illustrative. No answers, scores, attempts, or learner eligibility changes are saved.</p><p>{{ $questions->count() }} questions available for preview.</p><p id="preview-message" role="status"></p><div class="preview-start-actions"><button class="btn-primary" id="preview-begin">Start Preview</button><a class="btn-ghost" href="{{ route('admin.content.test-banks.manage', [$course, $testBank]) }}">Back to Question Bank</a></div></article></div>
<script>
const questions={{ Illuminate\Support\Js::from($questions) }},returnUrl={{ Illuminate\Support\Js::from(route('admin.content.test-banks.manage', [$course, $testBank])) }};
let index=0;const answers={},marked={},get=id=>document.getElementById(id);
function render(){const q=questions[index];if(!q){get('preview-question').textContent='No active questions are available. Add questions to this course to preview the simulation.';get('preview-next').disabled=true;get('preview-previous').disabled=true;return}get('preview-current').textContent=index+1;get('preview-progress').style.width=((index+1)/questions.length*100)+'%';get('preview-question').textContent=q.question;get('preview-image').replaceChildren();if(q.imageUrl){const image=document.createElement('img');image.src=q.imageUrl;image.alt='Question reference';image.style.cssText='max-width:100%;max-height:420px;object-fit:contain;border-radius:10px';get('preview-image').appendChild(image)}get('preview-options').replaceChildren();q.options.forEach((option,i)=>{const button=document.createElement('button');button.type='button';button.className='quiz-option'+(answers[index]===i?' selected':'');button.setAttribute('aria-pressed',answers[index]===i?'true':'false');const letter=document.createElement('span');letter.className='opt-letter';letter.textContent=String.fromCharCode(65+i);const text=document.createElement('span');text.textContent=option;button.append(letter,text);button.onclick=()=>{answers[index]=i;render()};get('preview-options').appendChild(button)});get('preview-previous').disabled=index===0;get('preview-mark').checked=!!marked[index];get('preview-next').textContent=index===questions.length-1?'Finish Preview':'Save & Continue'}
get('preview-begin').onclick=async()=>{try{const enter=document.documentElement.requestFullscreen||document.documentElement.webkitRequestFullscreen;if(enter)await enter.call(document.documentElement);get('preview-start').remove();render()}catch(error){get('preview-message').textContent='Please allow fullscreen to start the preview.'}};
get('preview-previous').onclick=()=>{if(index>0){index--;render()}};get('preview-next').onclick=()=>{if(index<questions.length-1){index++;render();document.querySelector('.exam-environment-body').scrollTop=0}else{alert('Preview complete. No attempt or score was recorded.');location.href=returnUrl}};get('preview-mark').onchange=event=>marked[index]=event.target.checked;get('preview-close').onclick=()=>location.href=returnUrl;
</script><script src="{{ asset('prometric-calculator.js') }}?v=5"></script></body></html>
